2.8 Integers and &lt;
Explain what is in this set, and why.
\[\left \{ x \in {\mathbb N}  \,|\,  \exists y \in {\mathbb N}\,\, y &lt; x \right\}\]

5 The Family of Normal Distributions

viewof mu = Inputs.range([-5, 5], {
  value: 0, 
  step: 0.1, 
  label: "μ:", 
  width: 250 
})

viewof sigma = Inputs.range([0.1, 3], {
  value: 1, 
  step: 0.1, 
  label: "σ:", 
  width: 250 
})

// 2. Dynamic Notation Display
// This updates instantly whenever the sliders move
md`### Distribution: N(${mu.toFixed(1)}, ${(sigma**2).toFixed(2)})`





















Plot.plot({
  height: 400,
  grid: true,
  y: { domain: [0, 1], label: "Density" },
  x: { domain: [-10, 10], label: "Value" },
  marks: [
    // The Normal Curve
    Plot.lineY(d3.range(-10, 10, 0.05), {
      x: x =&gt; x,
      y: x =&gt; (1 / (sigma * Math.sqrt(2 * Math.PI))) * Math.exp(-0.5 * Math.pow((x - mu) / sigma, 2)),
      stroke: "#2c3e50",
      strokeWidth: 3
    }),
    // A dashed vertical line at the mean to help visualize shift
    Plot.ruleX([mu], {stroke: "red", strokeDasharray: "4,4", opacity: 0.5})
  ]
})








The notation \(N(\mu, \sigma^2)\) refers to a normal distribution while telling its mean \(\mu\) and its standard deviation \(\sigma\). What kind of normal distribution is \(N(100,16)\)?

Visualizing the Standard Error

shape = 2;
scale = 5;
randomGamma = () =&gt; -Math.log(Math.random() * Math.random()) * scale;

// 2. STATIC SAMPLE (Does not depend on n or m, so it won't re-run)
staticSample = Array.from({ length: 1000 }, randomGamma);

// 3. REACTIVE SAMPLING DISTRIBUTION
samplingDistribution = {
  // This line ensures the cell re-runs when n or numSamples changes
  const _trigger = [n, numSamples]; 
  return Array.from({ length: numSamples }, () =&gt; {
    const s = Array.from({ length: n }, randomGamma);
    return d3.mean(s);
  });
}

// 4. STATS calculations
estimatedSE = d3.deviation(samplingDistribution);
meanOfMeans = d3.mean(samplingDistribution);



















































viewof n = Inputs.range([1, 100], {step: 1, value: 30, label: "Sample Size (n)"})
viewof numSamples = Inputs.range([1, 501], {step: 1, value: 31, label: "Number of Resamples (m)"})

















Population
(\(N=1000\))

Plot.plot({
  height: 400,
  style: { fontSize: "16px" },
  x: { domain: [0, 40], label: "Value"},
  y: { axis: null },
  marks: [
    Plot.ruleX([10], {stroke: "red", strokeDasharray: "4", strokeWidth: 2}),
    // The dodgeY transform stacks the dots on top of each other
    Plot.dot(staticSample, Plot.dodgeY({
      x: d =&gt; d, 
      anchor: "bottom", 
      fill: "#4e79a7", 
      r: 3
    })),
    Plot.text([10], {y: 0, text: d =&gt; "μ=10", dy: 20, fill: "red"})
  ]
})







Resampling Dist.
(Average of \(n\), done \(m\) times)

Plot.plot({
  height: 400,
  style: { fontSize: "16px" },
  x: { domain: [0, 40], label: "Sample Mean (x̄)" },
  y: { axis: null },
  marks: [
    Plot.ruleX([10], {stroke: "red", strokeDasharray: "4"}),
    Plot.dot(samplingDistribution, Plot.dodgeY({
      x: d =&gt; d, 
      anchor: "bottom",
      fill: "#e15759", 
      r: 2.5,
      fillOpacity: 0.7
    })),
//    Plot.ruleX([meanOfMeans], {stroke: "black", strokeWidth: 3})
  ]
})

🪙 100-Coin Flip-o-matic-inator
Adjust the slider to repeat the experiment of flipping \(100\) coins. We are counting the proportion of “Heads” (out of \(100\)) we get each time.

flip100Coins = () =&gt; {
  let heads = 0;
  for (let i = 0; i &lt; 100; i++) {
    if (Math.random() &gt; 0.5) heads++;
  }
  return heads/100;
}

// Reactive data array
flipData = {
  const _trigger = m;
  return Array.from({ length: m }, flip100Coins);
}
















viewof m = Inputs.range([1, 1000], {step: 1, value: 1, label: "Number of Experiments (m)"})







// 2. Plotting the results
Plot.plot({
  height: 500,
  style: { fontSize: "18px" },
  x: { 
    domain: [.30, .70], 
    label: "Number of Heads observed in 100 flips →",
    tickFormat: ".2f", 
    labelOffset: 50
  },
  y: { axis: null },
  marks: [
    // Expected value line (50)
    //Plot.ruleX([50], {stroke: "red", strokeDasharray: "4", strokeWidth: 2}),

    // The coin stacks
    Plot.dot(flipData, Plot.dodgeY({
      x: d =&gt; d, 
      anchor: "bottom", 
      fill: "#4e79a7", 
      r: 4,
      stroke: "white",
      strokeWidth: 0.5
    })),

  ]
})

